<span class="line"><span style="color:#C792EA;">async</span><span style="color:#C792EA;"> def</span><span style="color:#82AAFF;"> auth</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">ctx</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">MiddlewareContext</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> next</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">NextFn</span><span style="color:#89DDFF;">):</span></span>
